        print(run_line(run_label()[len("corrida "):], size_mb, metrics))
        if is_repetition(flow) and read_cycles(cycles_path):  # C5: el veredicto de memoria de esta corrida
            verdict, why = leak_verdict(read_cycles(cycles_path))
